If the plugin requires set-up that would slow down transfers, using a plugin initialization is recommended.
This includes things like querying the configuration file, performing a calculation that would not change
between different transfers, or hard-coding parameters.

This is done by including a initfunc when registering the plugin.

from rucio.transfertool.fts3plugins import FTS3TapeMetadataPlugin

class ExperimentFTSPlugins(FTS3TapeMetadataPlugin):
 def init(self, policyalgorithm="def"):
 self.register(
 "policyalgorithm",
 func=self.pluginalgorithm,
 initfunc=self.plugininitialization)
 super().init(policyalgorithm)

 def pluginalgorithm(self, hints):
 # Can use self.extraparams
 return {
 "storagelocation": self.extraparams[hints["name"]]
 }

 def plugininitialization(self):
 self.extraparams = dict(getconfig("transfers", "extraparams"))

